/* RecapRush Random Related Recap */
document.addEventListener("DOMContentLoaded",function(){
  var post=document.querySelector(".post-body");
  if(!post || document.querySelector(".rr-random-related")) return;

  function esc(s){
    return String(s==null?"":s).replace(/[&<>"']/g,function(c){
      return {"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c];
    });
  }

  function cleanUrl(url){
    try{
      var u=new URL(url,location.origin);
      u.search="";
      u.hash="";
      return u.pathname.replace(/\/+$/,"")||"/";
    }catch(e){
      return String(url||"").split("?")[0].split("#")[0].replace(/\/+$/,"");
    }
  }

  function chooseRandom(arr){
    return arr[Math.floor(Math.random()*arr.length)];
  }

  fetch("/feeds/posts/default?alt=json&max-results=30",{cache:"force-cache"})
    .then(function(r){
      if(!r.ok) throw new Error("Feed HTTP "+r.status);
      return r.json();
    })
    .then(function(data){
      var entries=(data&&data.feed&&Array.isArray(data.feed.entry))?data.feed.entry:[];
      if(!entries.length) return;

      var current=cleanUrl(location.href);
      var posts=entries.map(function(entry){
        var alt=(entry.link||[]).find(function(l){return l.rel==="alternate";});
        var href=alt&&alt.href?alt.href:"";
        var title=entry.title&&entry.title.$t?entry.title.$t:"";
        var thumb="";

        if(entry.media$thumbnail&&entry.media$thumbnail.url){
          thumb=entry.media$thumbnail.url
            .replace(/\/s72-c\//,"/s320/")
            .replace(/=s72-c$/,"=s320");
        }

        return {href:href,title:title,thumb:thumb};
      }).filter(function(p){
        return p.href && p.title && cleanUrl(p.href)!==current;
      });

      if(!posts.length) return;

      var pick=chooseRandom(posts);
      var box=document.createElement("aside");
      box.className="rr-random-related";
      box.setAttribute("aria-label","Related movie recap");

      var img=pick.thumb
        ? '<a class="rr-random-related-thumb" href="'+esc(pick.href)+'"><img src="'+esc(pick.thumb)+'" alt="'+esc(pick.title)+'" loading="lazy" decoding="async"></a>'
        : "";

      box.innerHTML=
        '<div class="rr-random-related-label">You May Also Like</div>'+
        '<div class="rr-random-related-inner">'+
          img+
          '<div class="rr-random-related-content">'+
            '<a class="rr-random-related-title" href="'+esc(pick.href)+'">'+esc(pick.title)+'</a>'+
            '<div class="rr-random-related-cta">Read another story →</div>'+
          '</div>'+
        '</div>';

      var headings=Array.from(post.querySelectorAll("h2")).filter(function(h){
        return !h.classList.contains("rr-auto-cast-title");
      });

      var target=null;
      var finalThoughts=headings.find(function(h){
        return /final thoughts/i.test(h.textContent||"");
      });

      if(headings.length>=6){
        target=headings[Math.max(2,Math.floor(headings.length/2))];
      }else if(finalThoughts){
        target=finalThoughts;
      }else if(headings.length>=2){
        target=headings[headings.length-1];
      }

      if(target&&target.parentNode){
        target.parentNode.insertBefore(box,target);
      }else{
        post.appendChild(box);
      }
    })
    .catch(function(){});
});


