/* =========================================================
   RecapRush V4 - Database Page Cleanup
   - Hide "You May Also Like" random related on database page
   - Hide comments on database page
   - Expand database page to full content width
   ========================================================= */
document.addEventListener("DOMContentLoaded", function(){
  var db = document.getElementById("rrDatabasePage");
  if(!db) return;

  document.documentElement.classList.add("rr-database-page");
  if(document.body) document.body.classList.add("rr-database-page");

  /* Hide random related block if already injected */
  Array.prototype.forEach.call(document.querySelectorAll(".rr-random-related"), function(el){
    el.style.setProperty("display","none","important");
  });

  /* Hide comment areas */
  var commentSelectors = [
    ".spotbuzz-pro-blog-post-comments",
    "#comments",
    ".comments",
    ".comment-form",
    ".post-footer .comments"
  ];
  commentSelectors.forEach(function(sel){
    Array.prototype.forEach.call(document.querySelectorAll(sel), function(el){
      el.style.setProperty("display","none","important");
    });
  });

  /* Watch for late-injected random related/comments */
  var obs = new MutationObserver(function(){
    Array.prototype.forEach.call(document.querySelectorAll(".rr-random-related"), function(el){
      el.style.setProperty("display","none","important");
    });
    commentSelectors.forEach(function(sel){
      Array.prototype.forEach.call(document.querySelectorAll(sel), function(el){
        el.style.setProperty("display","none","important");
      });
    });
  });
  obs.observe(document.body,{childList:true,subtree:true});
});

