/* =========================================================
   RecapRush V8 - Inline Movie Database Widget for Blogger posts

   Usage:
   <div class="rr-movie-db" data-movie-id="TMDB_ID" data-mode="full"></div>

   Modes:
   full    = Info + Similar + Reviews + Recommendations
   compact = Info + Similar + Recommendations
   ========================================================= */
document.addEventListener("DOMContentLoaded", function(){
  var widgets = document.querySelectorAll(".rr-movie-db[data-movie-id]");
  if(!widgets.length) return;

  var API_BASE = "https://movieinfo-api.mmololt1.workers.dev";
  var IMG342 = "https://image.tmdb.org/t/p/w342";

  function rrDbEsc(v){
    return String(v == null ? "" : v)
      .replace(/&/g,"&amp;")
      .replace(/</g,"&lt;")
      .replace(/>/g,"&gt;")
      .replace(/"/g,"&quot;")
      .replace(/'/g,"&#039;");
  }

  function rrDbFetch(url){
    return fetch(url,{method:"GET",mode:"cors",cache:"force-cache"})
      .then(function(r){
        if(!r.ok) throw new Error("HTTP "+r.status);
        return r.json();
      });
  }

  function rrMovieListHtml(items, recapMap, type){
    return (items || []).map(function(m){
      var title = m.title || m.original_title || "Untitled";
      var poster = m.poster_path
        ? IMG342 + m.poster_path
        : "https://placehold.co/342x513?text=No+Poster";
      var year = m.release_date ? String(m.release_date).slice(0,4) : "—";
      var rating = typeof m.vote_average === "number" ? m.vote_average.toFixed(1) : "—";
      var recap = recapMap && recapMap[String(m.id)] ? recapMap[String(m.id)] : null;
      var href = recap ? recap.url : "/?movie=" + encodeURIComponent(m.id);
      var badge = recap ? '<span class="rr-recap-badge">READ RECAP</span>' : "";

      return [
        '<article class="rr-inline-movie-card'+(recap?' rr-has-recap':'')+'">',
          '<a class="rr-inline-poster-link" href="'+href+'">',
            '<div class="rr-poster-wrap">'+badge,
              '<img class="rr-inline-poster" loading="lazy" decoding="async" src="'+poster+'" alt="'+rrDbEsc(title)+'"/>',
            '</div>',
          '</a>',
          '<a class="rr-inline-movie-title" href="'+href+'">'+rrDbEsc(title)+'</a>',
          '<div class="rr-inline-movie-meta">',
            '<span>'+rrDbEsc(year)+'</span>',
            '<span>•</span>',
            '<span>★ '+rrDbEsc(rating)+'</span>',
          '</div>',
        '</article>'
      ].join("");
    }).join("");
  }

  function renderWidget(box){
    var id = box.getAttribute("data-movie-id");
    var mode = (box.getAttribute("data-mode") || "full").toLowerCase();
    if(!id) return;

    box.classList.add("rr-movie-db-loading");
    box.innerHTML = '<div class="rr-inline-loading">Loading movie database...</div>';

    Promise.all([
      rrDbFetch(API_BASE + "/3/movie/" + encodeURIComponent(id) + "?language=en-US"),
      rrDbFetch(API_BASE + "/3/movie/" + encodeURIComponent(id) + "/credits?language=en-US")
        .catch(function(){ return {cast:[],crew:[]}; }),
      rrDbFetch(API_BASE + "/3/movie/" + encodeURIComponent(id) + "/similar?language=en-US&page=1")
        .catch(function(){ return {results:[]}; }),
      rrDbFetch(API_BASE + "/3/movie/" + encodeURIComponent(id) + "/reviews?language=en-US&page=1")
        .catch(function(){ return {results:[]}; }),
      rrDbFetch(API_BASE + "/3/movie/" + encodeURIComponent(id) + "/recommendations?language=en-US&page=1")
        .catch(function(){ return {results:[]}; })
    ])
    .then(function(all){
      var movie = all[0] || {};
      var credits = all[1] || {crew:[]};
      var similar = all[2] && Array.isArray(all[2].results) ? all[2].results.slice(0,6) : [];
      var reviews = all[3] && Array.isArray(all[3].results) ? all[3].results.slice(0,3) : [];
      var recs = all[4] && Array.isArray(all[4].results) ? all[4].results.slice(0,6) : [];
      var crew = Array.isArray(credits.crew) ? credits.crew : [];

      var directors = crew
        .filter(function(p){ return p.job === "Director"; })
        .map(function(p){ return p.name; });

      var companies = Array.isArray(movie.production_companies)
        ? movie.production_companies.map(function(c){ return c.name; }).slice(0,4)
        : [];

      var infoHtml = [
        '<section class="rr-inline-info-grid">',
          '<div class="rr-inline-info-card">',
            '<span class="rr-inline-info-label">Director</span>',
            '<strong>'+rrDbEsc(directors.length ? directors.join(", ") : "—")+'</strong>',
          '</div>',
          '<div class="rr-inline-info-card">',
            '<span class="rr-inline-info-label">Release Date</span>',
            '<strong>'+rrDbEsc(movie.release_date || "—")+'</strong>',
          '</div>',
          '<div class="rr-inline-info-card">',
            '<span class="rr-inline-info-label">Production Companies</span>',
            '<strong>'+rrDbEsc(companies.length ? companies.join(", ") : "—")+'</strong>',
          '</div>',
        '</section>'
      ].join("");

      var allMovies = similar.concat(recs);

      return (window.rrRecapMapForMovies
        ? window.rrRecapMapForMovies(allMovies)
        : Promise.resolve({})
      ).then(function(recapMap){
        var html = infoHtml;

        if(similar.length){
          html +=
            '<section class="rr-inline-section">'+
              '<h2 class="rr-inline-heading">Similar Movies</h2>'+
              '<div class="rr-inline-movie-grid">'+
                rrMovieListHtml(similar,recapMap,"similar")+
              '</div>'+
            '</section>';
        }

        if(mode !== "compact" && reviews.length){
          html += '<section class="rr-inline-section rr-inline-reviews">'+
            '<h2 class="rr-inline-heading">Reviews</h2>'+
            '<div class="rr-inline-review-list">';

          reviews.forEach(function(r){
            var author = r.author || "Anonymous";
            var content = r.content || "";
            var score = r.author_details && typeof r.author_details.rating === "number"
              ? r.author_details.rating + "/10"
              : "";

            if(content.length > 650){
              content = content.slice(0,650) + "…";
            }

            html +=
              '<article class="rr-inline-review-card">'+
                '<div class="rr-inline-review-head">'+
                  '<strong>'+rrDbEsc(author)+'</strong>'+
                  (score ? '<span>'+rrDbEsc(score)+'</span>' : '')+
                '</div>'+
                '<div class="rr-inline-review-text">'+rrDbEsc(content)+'</div>'+
              '</article>';
          });

          html += '</div></section>';
        }

        if(recs.length){
          html +=
            '<section class="rr-inline-section">'+
              '<h2 class="rr-inline-heading">Recommendations</h2>'+
              '<div class="rr-inline-movie-grid">'+
                rrMovieListHtml(recs,recapMap,"recommend")+
              '</div>'+
            '</section>';
        }

        box.classList.remove("rr-movie-db-loading");
        box.classList.add("rr-movie-db-ready");
        box.innerHTML = html;
      });
    })
    .catch(function(){
      box.classList.remove("rr-movie-db-loading");
      box.innerHTML = '<div class="rr-inline-error">Movie database could not be loaded.</div>';
    });
  }

  Array.prototype.forEach.call(widgets, renderWidget);
});

