/* =========================================================
   RecapRush V20 - Homepage 6-Post Pagination
   - Exactly 6 posts per page
   - Numbered pages + Previous / Next
   - Uses Blogger feed, bypassing Blogger's initial 3-post limit
   ========================================================= */
document.addEventListener("DOMContentLoaded", function(){
  try{
    var path = window.location.pathname || "/";
    var params = new URLSearchParams(window.location.search);
    var isHome = (path === "/" || path === "") &&
                 !params.has("movie") &&
                 !params.has("person") &&
                 !params.has("movies") &&
                 !params.has("q") &&
                 !params.has("genre");

    if(!isHome) return;

    var list = document.querySelector("#main .blog-posts, #main .hfeed");
    if(!list) return;

    var PAGE_SIZE = 6;
    var PAGE_WINDOW = 6;
    var currentPage = Math.max(1, parseInt(params.get("rrpage") || "1", 10) || 1);
    var totalPages = 1;
    var loading = false;

    function escHome(v){
      return String(v == null ? "" : v)
        .replace(/&/g,"&amp;")
        .replace(/</g,"&lt;")
        .replace(/>/g,"&gt;")
        .replace(/"/g,"&quot;")
        .replace(/'/g,"&#039;");
    }

    function cleanText(v){
      var div = document.createElement("div");
      div.innerHTML = String(v || "");
      return (div.textContent || div.innerText || "")
        .replace(/\s+/g," ")
        .trim();
    }

    function normalizeUrl(url){
      try{
        var u = new URL(url, location.origin);
        return (u.pathname || "/").replace(/\/+$/,"") || "/";
      }catch(e){
        return String(url || "").split("?")[0].split("#")[0].replace(/\/+$/,"");
      }
    }

    function entryUrl(entry){
      var links = entry && entry.link ? entry.link : [];
      for(var i=0;i<links.length;i++){
        if(links[i].rel === "alternate" && links[i].href) return links[i].href;
      }
      return "";
    }

    function entryImage(entry){
      var thumb = "";
      if(entry.media$thumbnail && entry.media$thumbnail.url){
        thumb = entry.media$thumbnail.url
          .replace(/\/s72-c\//,"/s640/")
          .replace(/=s72-c$/,"=s640")
          .replace(/\/s72-c$/,"/s640");
      }

      if(!thumb){
        var raw = "";
        if(entry.content && entry.content.$t) raw = entry.content.$t;
        else if(entry.summary && entry.summary.$t) raw = entry.summary.$t;

        var m = raw.match(/<img[^>]+src=["']([^"']+)["']/i);
        if(m && m[1]) thumb = m[1];
      }

      return thumb || "https://placehold.co/640x360?text=RecapRush";
    }

    function entryExcerpt(entry){
      var raw = "";
      if(entry.summary && entry.summary.$t) raw = entry.summary.$t;
      else if(entry.content && entry.content.$t) raw = entry.content.$t;
      var s = cleanText(raw);
      if(s.length > 145) s = s.slice(0,145).trim() + "...";
      return s;
    }

    function entryDate(entry){
      var raw = entry.published && entry.published.$t ? entry.published.$t : "";
      if(!raw) return "";
      var d = new Date(raw);
      if(isNaN(d.getTime())) return "";
      try{
        return d.toLocaleDateString("en-US",{
          month:"long",
          day:"2-digit",
          year:"numeric"
        });
      }catch(e){
        return "";
      }
    }

    function entryLabel(entry){
      var labels = entry.category || [];
      return labels.length && labels[0].term ? labels[0].term : "";
    }

    function entryAuthor(entry){
      return entry.author && entry.author[0] && entry.author[0].name
        ? entry.author[0].name.$t || ""
        : "";
    }

    function cardHtml(entry){
      var url = entryUrl(entry);
      var title = entry.title && entry.title.$t ? entry.title.$t : "Untitled";
      var image = entryImage(entry);
      var excerpt = entryExcerpt(entry);
      var date = entryDate(entry);
      var label = entryLabel(entry);
      var author = entryAuthor(entry);

      return [
        '<article class="blog-post hentry index-post rr-feed-post" data-rr-post-url="'+escHome(normalizeUrl(url))+'">',
          '<a class="rr-feed-image" href="'+escHome(url)+'">',
            '<img loading="lazy" decoding="async" src="'+escHome(image)+'" alt="'+escHome(title)+'"/>',
          '</a>',
          '<div class="rr-feed-content">',
            (label ? '<div class="rr-feed-label">'+escHome(label)+'</div>' : ''),
            '<h2 class="rr-feed-title"><a href="'+escHome(url)+'">'+escHome(title)+'</a></h2>',
            (excerpt ? '<p class="rr-feed-excerpt">'+escHome(excerpt)+'</p>' : ''),
            '<div class="rr-feed-meta">',
              (author ? '<span>by <a href="/">'+escHome(author)+'</a></span>' : ''),
              (date ? '<span>•</span><span>'+escHome(date)+'</span>' : ''),
            '</div>',
          '</div>',
        '</article>'
      ].join("");
    }

    function fetchPage(page){
      var startIndex = ((page - 1) * PAGE_SIZE) + 1;
      var url = "/feeds/posts/default?alt=json&max-results="+PAGE_SIZE+
                "&start-index="+encodeURIComponent(startIndex);

      return fetch(url,{credentials:"same-origin",cache:"no-store"})
        .then(function(r){
          if(!r.ok) throw new Error("Feed HTTP "+r.status);
          return r.json();
        })
        .then(function(data){
          var feed = data && data.feed ? data.feed : {};
          var entries = Array.isArray(feed.entry) ? feed.entry : [];
          var total = feed.openSearch$totalResults && feed.openSearch$totalResults.$t
            ? parseInt(feed.openSearch$totalResults.$t,10) || entries.length
            : entries.length;

          return {entries:entries,total:total};
        });
    }

    function makePager(){
      var oldPager = document.getElementById("blog-pager");
      if(oldPager) oldPager.style.setProperty("display","none","important");

      var existing = document.getElementById("rr-home-feed-pager");
      if(existing) return existing;

      var pager = document.createElement("nav");
      pager.id = "rr-home-feed-pager";
      pager.setAttribute("aria-label","Homepage pagination");

      if(oldPager && oldPager.parentNode){
        oldPager.parentNode.insertBefore(pager, oldPager.nextSibling);
      }else if(list.parentNode){
        list.parentNode.appendChild(pager);
      }
      return pager;
    }

    var pager = makePager();

    function renderPager(){
      var html = '<div class="rr-page-numbers">';

      html += '<button class="rr-page-btn rr-page-prev'+(currentPage<=1?' disabled':'')+
              '" type="button" data-page="'+(currentPage-1)+'"'+
              (currentPage<=1?' disabled':'')+'>‹ Prev</button>';

      if(totalPages <= 7){
        for(var p=1; p<=totalPages; p++){
          html += '<button class="rr-page-btn'+(p===currentPage?' active':'')+
                  '" type="button" data-page="'+p+'" aria-current="'+
                  (p===currentPage?'page':'false')+'">'+p+'</button>';
        }
      }else{
        var pages = [];

        if(currentPage <= 3){
          pages = [1,2,3];
        }else if(currentPage >= totalPages-2){
          pages = [Math.max(1,totalPages-2), Math.max(1,totalPages-1), totalPages];
        }else{
          pages = [currentPage-1,currentPage,currentPage+1];
        }

        var firstShown = pages[0];
        var lastShown = pages[pages.length-1];

        if(firstShown > 1){
          html += '<button class="rr-page-btn" type="button" data-page="1">1</button>';
          if(firstShown > 2){
            html += '<span class="rr-page-dots">…</span>';
          }
        }

        pages.forEach(function(p){
          if(p < 1 || p > totalPages) return;
          html += '<button class="rr-page-btn'+(p===currentPage?' active':'')+
                  '" type="button" data-page="'+p+'" aria-current="'+
                  (p===currentPage?'page':'false')+'">'+p+'</button>';
        });

        if(lastShown < totalPages){
          if(lastShown < totalPages-1){
            html += '<span class="rr-page-dots">…</span>';
          }
          html += '<button class="rr-page-btn" type="button" data-page="'+
                  totalPages+'">'+totalPages+'</button>';
        }
      }

      html += '<button class="rr-page-btn rr-page-next'+(currentPage>=totalPages?' disabled':'')+
              '" type="button" data-page="'+(currentPage+1)+'"'+
              (currentPage>=totalPages?' disabled':'')+'>Next ›</button>';

      html += '</div><div id="rr-home-loading" style="display:none">Loading...</div>';
      pager.innerHTML = html;

      Array.prototype.forEach.call(pager.querySelectorAll("[data-page]"), function(btn){
        btn.addEventListener("click", function(){
          if(btn.disabled) return;
          var page = parseInt(btn.getAttribute("data-page"),10);
          if(!page || page < 1 || page > totalPages || page === currentPage || loading) return;
          loadPage(page, true);
        });
      });
    }

    function setUrlPage(page){
      try{
        var u = new URL(window.location.href);
        if(page <= 1) u.searchParams.delete("rrpage");
        else u.searchParams.set("rrpage", String(page));
        history.pushState({rrpage:page},"",u.pathname+(u.searchParams.toString()?"?"+u.searchParams.toString():""));
      }catch(e){}
    }

    function loadPage(page, updateUrl){
      if(loading) return;
      loading = true;

      pager.classList.add("is-loading");

      fetchPage(page).then(function(result){
        totalPages = Math.max(1, Math.ceil(result.total / PAGE_SIZE));

        if(page > totalPages){
          page = totalPages;
          return fetchPage(page).then(function(last){
            result = last;
            return result;
          });
        }
        return result;
      }).then(function(result){
        currentPage = page;
        list.innerHTML = result.entries.map(cardHtml).join("");

        renderPager();

        if(updateUrl) setUrlPage(currentPage);

        if(updateUrl){
          try{
            list.scrollIntoView({behavior:"smooth",block:"start"});
          }catch(e){}
        }
      }).catch(function(){
        pager.innerHTML = '<div class="rr-home-page-error">Could not load posts. Please try again.</div>';
      }).finally(function(){
        loading = false;
        pager.classList.remove("is-loading");
      });
    }

    window.addEventListener("popstate", function(){
      var p = new URLSearchParams(window.location.search);
      var page = Math.max(1,parseInt(p.get("rrpage") || "1",10) || 1);
      loadPage(page,false);
    });

    /* Replace Blogger's partial homepage output with exactly 6 feed posts. */
    list.innerHTML = "";
    pager.innerHTML = '<div id="rr-home-loading">Loading...</div>';
    loadPage(currentPage,false);

  }catch(e){}
});

