/* =========================================================
   RecapRush V21 - Auto Movie TV Schema
   Automatically styles the first table after an H2 titled "Quick Facts".
   No extra class is required in Blogger posts.
   ========================================================= */
document.addEventListener("DOMContentLoaded", function(){
  try{
    var bodies = document.querySelectorAll(".post-body, .entry-content");
    if(!bodies.length) return;

    Array.prototype.forEach.call(bodies, function(body){
      var headings = body.querySelectorAll("h2");
      Array.prototype.forEach.call(headings, function(h2){
        var title = (h2.textContent || "").replace(/\s+/g," ").trim().toLowerCase();
        if(title !== "quick facts") return;

        var next = h2.nextElementSibling;
        while(next && next.tagName !== "TABLE"){
          next = next.nextElementSibling;
        }

        if(next && next.tagName === "TABLE"){
          next.classList.add("rr-quickfacts");
        }
      });
    });
  }catch(e){}
});

