/* =========================================================
   RecapRush V19 - TMDB Browser RecapRush News Pagination
   - Applies only to ?movies=all pages
   - 8 RecapRush articles per page
   - Loads up to 500 matching Blogger posts once, then paginates locally
   - Genre-aware Blogger label feed
   ========================================================= */
document.addEventListener("DOMContentLoaded", function(){
  try{
    var params = new URLSearchParams(window.location.search);
    if(params.get("movies") !== "all") return;

    var postList = document.querySelector("#main .blog-posts, #main .hfeed");
    if(!postList) return;

    var PAGE_SIZE = 8;
    var PAGE_WINDOW = 6;
    var loading = false;
    var allEntries = [];

    var genreMap = {
      "28":"Action",
      "12":"Adventure",
      "16":"Animation",
      "35":"Comedy",
      "80":"Crime",
      "99":"Documentary",
      "18":"Drama",
      "10751":"Family",
      "14":"Fantasy",
      "36":"History",
      "27":"Horror",
      "10402":"Music",
      "9648":"Mystery",
      "10749":"Romance",
      "878":"Sci-Fi",
      "10770":"TV News",
      "53":"Thriller",
      "10752":"War",
      "37":"Western"
    };

    var genreId = params.get("genre") || "";
    var bloggerLabel = genreMap[String(genreId)] || "";
    var currentPage = Math.max(1, parseInt(params.get("newsPage") || "1",10) || 1);
    var totalPages = 1;

    function esc(v){
      return String(v == null ? "" : v)
        .replace(/&/g,"&amp;")
        .replace(/</g,"&lt;")
        .replace(/>/g,"&gt;")
        .replace(/"/g,"&quot;")
        .replace(/'/g,"&#039;");
    }

    function cleanText(v){
      var div=document.createElement("div");
      div.innerHTML=String(v||"");
      return (div.textContent||div.innerText||"").replace(/\s+/g," ").trim();
    }

    function entryUrl(entry){
      var links=entry&&entry.link?entry.link:[];
      for(var i=0;i<links.length;i++){
        if(links[i].rel==="alternate"&&links[i].href) return links[i].href;
      }
      return "";
    }

    function entryImage(entry){
      var thumb="";
      if(entry.media$thumbnail&&entry.media$thumbnail.url){
        thumb=entry.media$thumbnail.url
          .replace(/\/s72-c\//,"/s640/")
          .replace(/=s72-c$/,"=s640")
          .replace(/\/s72-c$/,"/s640");
      }
      if(!thumb){
        var raw="";
        if(entry.content&&entry.content.$t) raw=entry.content.$t;
        else if(entry.summary&&entry.summary.$t) raw=entry.summary.$t;
        var m=raw.match(/<img[^>]+src=["']([^"']+)["']/i);
        if(m&&m[1]) thumb=m[1];
      }
      return thumb||"https://placehold.co/640x360?text=RecapRush";
    }

    function entryDate(entry){
      var raw=entry.published&&entry.published.$t?entry.published.$t:"";
      if(!raw) return "";
      var d=new Date(raw);
      if(isNaN(d.getTime())) return "";
      try{
        return d.toLocaleDateString("en-US",{
          month:"short",
          day:"02-digit",
          year:"numeric"
        });
      }catch(e){ return ""; }
    }

    function entryLabel(entry){
      var labels=entry.category||[];
      return labels.length&&labels[0].term?labels[0].term:"";
    }

    function entryExcerpt(entry){
      var raw="";
      if(entry.summary&&entry.summary.$t) raw=entry.summary.$t;
      else if(entry.content&&entry.content.$t) raw=entry.content.$t;
      var s=cleanText(raw);
      if(s.length>110) s=s.slice(0,110).trim()+"...";
      return s;
    }

    function cardHtml(entry){
      var url=entryUrl(entry);
      var title=entry.title&&entry.title.$t?entry.title.$t:"Untitled";
      var image=entryImage(entry);
      var date=entryDate(entry);
      var label=entryLabel(entry);
      var excerpt=entryExcerpt(entry);

      return [
        '<article class="rr-tmdb-news-card">',
          '<a class="rr-tmdb-news-image" href="'+esc(url)+'">',
            '<img loading="lazy" decoding="async" src="'+esc(image)+'" alt="'+esc(title)+'"/>',
          '</a>',
          '<div class="rr-tmdb-news-body">',
            (label?'<div class="rr-tmdb-news-label">'+esc(label)+'</div>':''),
            '<h3 class="rr-tmdb-news-title"><a href="'+esc(url)+'">'+esc(title)+'</a></h3>',
            (excerpt?'<p class="rr-tmdb-news-excerpt">'+esc(excerpt)+'</p>':''),
            (date?'<div class="rr-tmdb-news-date">'+esc(date)+'</div>':''),
          '</div>',
        '</article>'
      ].join("");
    }

    function feedUrl(){
      var base="/feeds/posts/default";
      if(bloggerLabel){
        base+="/-/"+encodeURIComponent(bloggerLabel);
      }
      return base+"?alt=json&max-results=500";
    }

    function fetchAll(){
      return fetch(feedUrl(),{
        credentials:"same-origin",
        cache:"no-store"
      })
      .then(function(r){
        if(!r.ok) throw new Error("Feed HTTP "+r.status);
        return r.json();
      })
      .then(function(data){
        var feed=data&&data.feed?data.feed:{};
        return Array.isArray(feed.entry)?feed.entry:[];
      });
    }

    function getHeading(){
      var existing=document.getElementById("rr-tmdb-news-heading");
      if(existing) return existing;

      var heading=document.createElement("div");
      heading.id="rr-tmdb-news-heading";
      heading.className="rr-tmdb-news-heading";
      heading.innerHTML=
        '<h2>'+(bloggerLabel?esc(bloggerLabel)+" RecapRush Articles":"Latest RecapRush Articles")+'</h2>';

      postList.parentNode.insertBefore(heading,postList);
      return heading;
    }

    function getPager(){
      var old=document.getElementById("rr-tmdb-news-pager");
      if(old) return old;

      var pager=document.createElement("nav");
      pager.id="rr-tmdb-news-pager";
      pager.setAttribute("aria-label","RecapRush article pagination");
      postList.parentNode.insertBefore(pager,postList.nextSibling);
      return pager;
    }

    getHeading();
    var pager=getPager();

    function renderPager(){
      if(totalPages<=1){
        pager.innerHTML="";
        return;
      }

      var startPage=Math.floor((currentPage-1)/PAGE_WINDOW)*PAGE_WINDOW+1;
      var endPage=Math.min(totalPages,startPage+PAGE_WINDOW-1);
      var html='<div class="rr-tmdb-page-numbers">';

      if(currentPage>1){
        html+='<button type="button" class="rr-tmdb-page-btn rr-tmdb-prev" data-news-page="'+(currentPage-1)+'">‹ Prev</button>';
      }

      for(var p=startPage;p<=endPage;p++){
        html+='<button type="button" class="rr-tmdb-page-btn'+(p===currentPage?' active':'')+'" data-news-page="'+p+'">'+p+'</button>';
      }

      if(currentPage<totalPages){
        html+='<button type="button" class="rr-tmdb-page-btn rr-tmdb-next" data-news-page="'+(currentPage+1)+'">Next ›</button>';
      }

      html+='</div>';
      pager.innerHTML=html;

      Array.prototype.forEach.call(pager.querySelectorAll("[data-news-page]"),function(btn){
        btn.addEventListener("click",function(){
          var p=parseInt(btn.getAttribute("data-news-page"),10);
          if(!p||p===currentPage||loading) return;
          renderPage(p,true);
        });
      });
    }

    function updateUrl(page){
      try{
        var u=new URL(window.location.href);
        if(page<=1) u.searchParams.delete("newsPage");
        else u.searchParams.set("newsPage",String(page));
        history.pushState(
          {newsPage:page},
          "",
          u.pathname+"?"+u.searchParams.toString()
        );
      }catch(e){}
    }

    function renderPage(page,updateHistory){
      totalPages=Math.max(1,Math.ceil(allEntries.length/PAGE_SIZE));
      currentPage=Math.min(Math.max(1,page),totalPages);

      var start=(currentPage-1)*PAGE_SIZE;
      var pageEntries=allEntries.slice(start,start+PAGE_SIZE);

      postList.innerHTML=pageEntries.map(cardHtml).join("");
      renderPager();

      if(updateHistory) updateUrl(currentPage);

      if(updateHistory){
        try{
          var heading=document.getElementById("rr-tmdb-news-heading");
          if(heading) heading.scrollIntoView({behavior:"smooth",block:"start"});
        }catch(e){}
      }
    }

    window.addEventListener("popstate",function(){
      var p=new URLSearchParams(window.location.search);
      var page=Math.max(1,parseInt(p.get("newsPage")||"1",10)||1);
      renderPage(page,false);
    });

    var nativePager=document.getElementById("blog-pager");
    if(nativePager) nativePager.style.setProperty("display","none","important");

    postList.innerHTML="";
    postList.classList.add("rr-tmdb-news-grid");
    postList.innerHTML='<div class="rr-tmdb-news-loading">Loading RecapRush articles...</div>';

    loading=true;
    fetchAll()
      .then(function(entries){
        allEntries=entries;
        renderPage(currentPage,false);
      })
      .catch(function(){
        postList.innerHTML='<div class="rr-tmdb-news-error">Could not load RecapRush articles.</div>';
        pager.innerHTML="";
      })
      .finally(function(){
        loading=false;
      });

  }catch(e){}
});

