/* =========================================================
   RecapRush V21 - Automatic Movie / TVSeries JSON-LD Schema
   Uses TMDB IDs already present in RecapRush post widgets.
   Movie:
     <div class="rr-auto-cast" data-movie-id="123"></div>
     or <div class="rr-movie-db" data-movie-id="123"></div>
   TV:
     <div class="rr-auto-cast" data-tv-id="123"></div>
   ========================================================= */
document.addEventListener("DOMContentLoaded", function(){
  try{
    var post = document.querySelector(".post-body, .entry-content");
    if(!post) return;

    if(document.getElementById("rr-auto-media-schema")) return;

    var movieNode = post.querySelector("[data-movie-id]");
    var tvNode = post.querySelector("[data-tv-id]");

    var type = tvNode ? "tv" : (movieNode ? "movie" : "");
    var id = tvNode
      ? tvNode.getAttribute("data-tv-id")
      : (movieNode ? movieNode.getAttribute("data-movie-id") : "");

    if(!type || !id) return;

    var API_BASE = "https://movieinfo-api.mmololt1.workers.dev";
    var detailUrl = API_BASE + "/3/" + type + "/" + encodeURIComponent(id) + "?language=en-US";
    var creditsUrl = API_BASE + "/3/" + type + "/" + encodeURIComponent(id) + "/credits?language=en-US";

    function fetchJson(url){
      return fetch(url,{cache:"force-cache"}).then(function(r){
        if(!r.ok) throw new Error("HTTP "+r.status);
        return r.json();
      });
    }

    function cleanText(v){
      return String(v == null ? "" : v).replace(/\s+/g," ").trim();
    }

    function compactArray(arr){
      return (arr || []).filter(function(v){ return !!v; });
    }

    function pageTitle(){
      var h1 = document.querySelector("h1.entry-title, h1.post-title, .entry-title, .post-title");
      return cleanText(h1 && h1.textContent ? h1.textContent : document.title);
    }

    function pageDescription(){
      var meta = document.querySelector('meta[name="description"]');
      if(meta && meta.content) return cleanText(meta.content);

      var p = post.querySelector("p");
      return cleanText(p && p.textContent ? p.textContent : "");
    }

    function canonicalUrl(){
      var canonical = document.querySelector('link[rel="canonical"]');
      return canonical && canonical.href ? canonical.href : window.location.href.split("#")[0];
    }

    Promise.all([
      fetchJson(detailUrl),
      fetchJson(creditsUrl).catch(function(){ return {cast:[],crew:[]}; })
    ]).then(function(all){
      var media = all[0] || {};
      var credits = all[1] || {};
      var cast = Array.isArray(credits.cast) ? credits.cast : [];
      var crew = Array.isArray(credits.crew) ? credits.crew : [];

      var genres = Array.isArray(media.genres)
        ? compactArray(media.genres.map(function(g){ return g && g.name ? cleanText(g.name) : ""; }))
        : [];

      var actors = cast.slice(0,10).map(function(p){
        var actor = {
          "@type":"Person",
          "name":cleanText(p.name || p.original_name || "Unknown")
        };
        if(p.id) actor.url = window.location.origin + "/?person=" + encodeURIComponent(p.id);
        return actor;
      }).filter(function(p){ return p.name && p.name !== "Unknown"; });

      var directors = [];
      if(type === "movie"){
        directors = crew.filter(function(p){
          return p && p.job === "Director" && p.name;
        }).map(function(p){
          var director = {"@type":"Person","name":cleanText(p.name)};
          if(p.id) director.url = window.location.origin + "/?person=" + encodeURIComponent(p.id);
          return director;
        });
      }else{
        var creators = Array.isArray(media.created_by) ? media.created_by : [];
        directors = creators.map(function(p){
          var creator = {"@type":"Person","name":cleanText(p.name || "")};
          if(p.id) creator.url = window.location.origin + "/?person=" + encodeURIComponent(p.id);
          return creator;
        }).filter(function(p){ return !!p.name; });
      }

      var posterPath = media.poster_path || "";
      var backdropPath = media.backdrop_path || "";
      var images = compactArray([
        posterPath ? "https://image.tmdb.org/t/p/w780" + posterPath : "",
        backdropPath ? "https://image.tmdb.org/t/p/w1280" + backdropPath : ""
      ]);

      var schema = {
        "@context":"https://schema.org",
        "@type": type === "tv" ? "TVSeries" : "Movie",
        "name": cleanText(media.title || media.name || media.original_title || media.original_name || pageTitle()),
        "url": canonicalUrl(),
        "description": cleanText(media.overview || pageDescription())
      };

      if(images.length === 1) schema.image = images[0];
      else if(images.length > 1) schema.image = images;

      if(genres.length) schema.genre = genres;
      if(actors.length) schema.actor = actors;

      if(type === "movie"){
        if(media.release_date) schema.dateCreated = media.release_date;
        if(directors.length) schema.director = directors;
        if(media.runtime) schema.duration = "PT" + parseInt(media.runtime,10) + "M";
      }else{
        if(media.first_air_date) schema.dateCreated = media.first_air_date;
        if(media.last_air_date) schema.dateModified = media.last_air_date;
        if(directors.length) schema.creator = directors;
        if(typeof media.number_of_seasons === "number") schema.numberOfSeasons = media.number_of_seasons;
        if(typeof media.number_of_episodes === "number") schema.numberOfEpisodes = media.number_of_episodes;
      }

      if(media.production_companies && Array.isArray(media.production_companies)){
        var companies = media.production_companies.slice(0,5).map(function(c){
          return c && c.name ? {"@type":"Organization","name":cleanText(c.name)} : null;
        }).filter(Boolean);

        if(companies.length){
          schema.productionCompany = companies;
        }
      }

      /* No fabricated Review or aggregateRating is added.
         Add those only when a real visible RecapRush rating/review exists on the page. */

      var script = document.createElement("script");
      script.id = "rr-auto-media-schema";
      script.type = "application/ld+json";
      script.textContent = JSON.stringify(schema);
      document.head.appendChild(script);
    }).catch(function(){});
  }catch(e){}
});
